# ==============================================================================
# STUDY       : SOMMA
# PROGRAM     : 03_calc_entropy.R
#
# PURPOSE     : Calculate proteomic entropy measures for the SOMMA Parent
#               cohort using SOMMA Jr as the reference population.
#
# INPUTS      : - Preprocessed SomaLogic proteomic datasets generated by
#                 02_preprocess_data.R
#               - Phenotypic and demographic variables included in the
#                 preprocessed datasets
#               - Entropy-related functions defined in 99_entropy_methods.R
#
# OUTPUTS     : - Mahalanobis-distance entropy measures using PCA-based and
#                 shrinkage covariance estimation
#               - DISCO entropy measures
#               - Quartile classifications of entropy measures
#               - Sex-specific entropy measures
#               - Entropy measure correlation matrix and figure
#
# DATA ACCESS : Individual-level SOMMA data are not included in this
#               repository. Access to the underlying study data is required
#               to reproduce the analyses.
#
# DEPENDENCIES:
#               - R
#               - data.table
#               - corrplot
#               - RColorBrewer
#               - Additional functions and objects defined in
#                 99_analysis_setup.R and 99_entropy_methods.R
#
# VERSION     : 1.0
# DATE        : 2025-11-29
# AUTHOR      : Tyler Mansfield
#
# REVISION HISTORY
# 11/29/25    Creation
# 01/30/26    Added sex-specific entropy
#
# NOTES       : SOMMA Jr is used as the reference population for calculation
#               of entropy measures in SOMMA Parent participants.
#               Local file paths are specified separately from the analysis
#               code and should be configured for the user's environment.
# ==============================================================================

source("code/99_analysis_setup.R")


### Main function: calculate the entropy measures ----------------------------------

calculate_entropy_metrics <- function(dataset)
{
  # Read in data
  apt_names <- names(dataset)[str_detect(names(dataset), "seq")]
  parent_IDs <- dataset[COHORT == "Parent", ]$ID
  jr_IDs <- dataset[COHORT == "Jr", ]$ID
  
  message("Found ", length(apt_names), " aptamers")
  message("Found ", length(parent_IDs), " SOMMA parent participants")
  message("Found ", length(jr_IDs), " SOMMA Jr participants")
  
  # Extract the SOMMA parent data and Jr means
  parent_data_apt <- dataset[match(parent_IDs, ID), mget(apt_names)]
  parent_data_center <- parent_data_apt %>%
    sapply(median)
  jr_data_apt <- dataset[match(jr_IDs, ID), mget(apt_names)]
  jr_data_center <- jr_data_apt %>%
    sapply(median)
  
  # Find M-distance (JR Center, PCA)
  mdist_res_jr_center <- mahalanobis_pca(parent_data_apt, 
                                         apt_names, 
                                         centroid = jr_data_center,
                                         min_eigval = 1e-20)$dist
  
  # Find M-distance (Jr Center, shrink)
  mdist_res_jr_center_shrink <- mahalanobis_shrinkage(parent_data_apt, 
                                                      apt_names, 
                                                      centroid = jr_data_center)
  
  
  # Find DISCO
  age_assoc <- cor(all_data[match(parent_IDs, ID), mget(apt_names)], 
                   all_data[match(parent_IDs, ID), mget("D1AGE2")]) %>%
    as.vector()
  names(age_assoc) <- apt_names
  
  disco_res_jr <- DISCO_fast(ref_dt = jr_data_apt,
                             target_dt = parent_data_apt, 
                             apt_names,
                             age_assoc)
  
  # Assemble results 
  entropy_measures_add <- data.table(ID = as.character(parent_IDs), 
                                     DM_JRPCA = mdist_res_jr_center,
                                     DM_JRSHRINK = mdist_res_jr_center_shrink,
                                     DISCO_JR = disco_res_jr)
  
  # Add quartiles (1 = lowest, 4 = highest)
  entropy_cols <- c("DM_JRPCA", "DM_JRSHRINK", "DISCO_JR")
  
  entropy_measures_add[, paste0(entropy_cols, "_Q") :=
                         lapply(.SD, function(x)
                           data.table::frank(x, ties.method = "average", na.last = "keep") |>
                             cut(
                               breaks = quantile(
                                 data.table::frank(x, ties.method = "average", na.last = "keep"),
                                 probs = seq(0, 1, 0.25),
                                 na.rm = TRUE
                               ),
                               include.lowest = TRUE,
                               labels = 1:4
                             ) |>
                             as.integer()
                         ),
                       .SDcols = entropy_cols
  ]
  
  return(entropy_measures_add)
}

# helper function to rename entropy + quartile columns
rename_entropy_cols <- function(dt, prefix, suffix = "")
{
  old_names <- c(entropy_methods,
                 paste0(entropy_methods, "_Q"))
  
  new_names <- c(
    paste0(prefix, "_", entropy_methods, suffix),
    paste0(prefix, "_", entropy_methods, "_Q", suffix)
  )
  
  setnames(dt, old = old_names, new = new_names)
  return(dt)
}


all_transform_results <- list()

for (data_transform in data_transforms)
{
  message("====================================================")
  message("Running transform: ", data_transform)
  message("====================================================")
  
  # Read in transformed dataset
  all_data <- fread(
    file.path(
      PATH_DATA,
      paste0(
        "02_",
        data_transform,
        "_transformed_data_with_pheno.csv"
      )
    )
  )
  
  # --------------------------------------------------------------------------
  # ALL PARTICIPANTS
  # --------------------------------------------------------------------------
  
  entropy_metrics <- calculate_entropy_metrics(
    dataset = all_data
  ) |>
    rename_entropy_cols(
      prefix = toupper(data_transform)
    )
  
  # --------------------------------------------------------------------------
  # MEN
  # --------------------------------------------------------------------------
  
  entropy_metrics_men <- calculate_entropy_metrics(
    dataset = all_data[EEFEMALE == 0]
  ) |>
    rename_entropy_cols(
      prefix = toupper(data_transform),
      suffix = "_MEN"
    )
  
  # --------------------------------------------------------------------------
  # WOMEN
  # --------------------------------------------------------------------------
  
  entropy_metrics_women <- calculate_entropy_metrics(
    dataset = all_data[EEFEMALE == 1]
  ) |>
    rename_entropy_cols(
      prefix = toupper(data_transform),
      suffix = "_WOMEN"
    )
  
  # --------------------------------------------------------------------------
  # MERGE RESULTS
  # --------------------------------------------------------------------------
  
  transform_results <- merge(
    entropy_metrics,
    entropy_metrics_men,
    by = "ID",
    all = TRUE
  ) |>
    merge(
      entropy_metrics_women,
      by = "ID",
      all = TRUE
    ) |>
    as.data.table()
  
  # --------------------------------------------------------------------------
  # CREATE SEX-SPECIFIC COMBINED COLUMNS
  # --------------------------------------------------------------------------
  
  for (m in entropy_methods)
  {
    men_col <- paste0(
      toupper(data_transform),
      "_",
      m,
      "_MEN"
    )
    
    women_col <- paste0(
      toupper(data_transform),
      "_",
      m,
      "_WOMEN"
    )
    
    new_col <- paste0(
      toupper(data_transform),
      "_",
      m,
      "_SEXSP"
    )
    
    transform_results[
      ,
      (new_col) :=
        fifelse(
          !is.na(get(men_col)),
          get(men_col),
          get(women_col)
        )
    ]
  }
  
  # Save to list
  all_transform_results[[data_transform]] <- transform_results
}


# ============================================================================
# MERGE ALL TRANSFORMATION RESULTS TOGETHER
# ============================================================================

all_entropy_results <- Reduce(
  function(x, y)
    merge(x, y, by = "ID", all = TRUE),
  all_transform_results) |> 
  as.data.table()


# ============================================================================
# SAVE FINAL RESULTS
# ============================================================================

fwrite(
  all_entropy_results,
  file.path(PATH_OUTPUT, "05_entropy_measures.csv")
)